<?php
/**
 * Plugin Name: NESports Auto Updater V14
 * Description: Normalizes shirt sizes in Shop by Color, adds model shots per card, fixes Green card-in-card, fixes Grey bag color.
 * Version: 14.0.0
 * Author: NESports
 */

function run_nesports_master_update() {
    $target_dirs = array(
        WP_PLUGIN_DIR . '/nesports-pro',
        WP_PLUGIN_DIR . '/nesports-pro-store'
    );
    
    $payloads = array(
        'includes/helpers.php' => base64_decode(''),
        'templates/sections/section-color.php' => base64_decode(''),
        'assets/images/clothing/norm-lift-the-world-red.jpg' => base64_decode(''),
        'assets/images/clothing/norm-pro-coach-red.jpg' => base64_decode(''),
        'assets/images/clothing/norm-strength-club-red.jpg' => base64_decode(''),
        'assets/images/clothing/norm-strength-club-red-front.jpg' => base64_decode(''),
        'assets/images/clothing/norm-pro-coach-green.jpg' => base64_decode(''),
        'assets/images/clothing/norm-pro-coach-green-front.jpg' => base64_decode(''),
        'assets/images/clothing/norm-lift-the-world-black.jpg' => base64_decode(''),
        'assets/images/clothing/norm-strength-club-black.jpg' => base64_decode(''),
        'assets/images/clothing/norm-strength-club-black-front.jpg' => base64_decode(''),
        'assets/images/clothing/norm-strength-club-blue.jpg' => base64_decode(''),
        'assets/images/clothing/norm-strength-club-blue-front.jpg' => base64_decode(''),
        'assets/images/clothing/norm-pro-coach-navy.jpg' => base64_decode(''),
        'assets/images/clothing/model-lift-the-world-red-sq.jpg' => base64_decode(''),
        'assets/images/clothing/model-pro-coach-red-sq.jpg' => base64_decode(''),
        'assets/images/clothing/model-pro-coach-green-sq.jpg' => base64_decode(''),

    );
    
    $results = array();
    foreach ($target_dirs as $td) {
        if (!is_dir($td)) continue;
        $results[$td] = array();
        foreach ($payloads as $rel => $data) {
            $dest = $td . '/' . $rel;
            $d = dirname($dest);
            if (!is_dir($d)) {
                wp_mkdir_p($d);
            }
            $w = file_put_contents($dest, $data);
            $results[$td][$rel] = ($w !== false) ? "SUCCESS ($w bytes)" : "ERROR";
        }
    }
    return $results;
}

add_action('init', function() {
    if (isset($_GET['nesports_apply_update']) && $_GET['nesports_apply_update'] === '1') {
        $res = run_nesports_master_update();
        header('Content-Type: application/json');
        echo json_encode(array('status' => 'ok', 'results' => $res));
        exit;
    }
});

register_activation_hook(__FILE__, function() {
    run_nesports_master_update();
});
